/**
 * SSO channel route handlers: authorize redirect + callback exchange.
 *
 * Flow (minimal closed loop):
 *   GET /api/auth/sso/authorize  → 302 IDaaS authorize (state minted server-side)
 *   IDaaS 302 back               → GET /api/auth/sso/callback?code&state
 *     ① state compared + consumed once (CSRF)
 *     ② backend POST token endpoint (JSON body client_id/secret — the secret
 *        never leaves the server process)
 *     ③ userinfo → 工号 → auto-provision the UserStore record on first login
 *        (the first SSO login ever becomes the admin; later ones are ordinary)
 *     ④ dsh-login session issued, cookie set, 302 to /
 *
 * Every failure bounces to /login?error=sso_<code> — coarse codes only, never
 * tokens/codes/secret values.
 */
import { randomBytes } from 'node:crypto'
import { appendFileSync, existsSync } from 'node:fs'
import type { ServerResponse, IncomingMessage } from 'node:http'
import type { WebRoute } from '@deepseek-ai/dsh-host-webserver'
import type { SessionStore } from './session.ts'
import type { UserStore, UserRecord } from './users.ts'
import { buildCookieHeader } from './auth.ts'
import {
  buildAuthorizeUrl,
  exchangeCode,
  fetchUserInfo,
  resolveRedirectUri,
  resolveUid,
  type SsoConfig,
  type SsoErrorCode,
  type SsoStateStore,
} from './sso.ts'

/** Shared dependencies for the callback handler. */
export interface SsoCallbackDeps {
  cfg: SsoConfig
  users: UserStore
  store: SessionStore
  /** Session lifetime in seconds; stamped onto the Set-Cookie Max-Age. */
  sessionTtl: number
  states: SsoStateStore
  /** Resolve the client secret from the DSH credentials system. */
  resolveSecret: () => Promise<string | undefined>
}

/**
 * 排障 trace（marker 文件 /tmp/dsh-sso-debug 存在时启用）：
 * 只记阶段、状态码、字段名——绝不记 secret/token/code/字段值。
 */
function ssoTrace(line: string): void {
  try {
    if (!existsSync('/tmp/dsh-sso-debug')) return
    appendFileSync('/tmp/dsh-sso-trace.log', `${new Date().toISOString()} ${line}\n`, { mode: 0o600 })
  } catch {
    /* 排障辅助不引入新故障：静默 */
  }
}

/**
 * GET /api/auth/sso/authorize — mint a one-time state and 302 to the IDaaS
 * authorize endpoint. No session required: this is the front door.
 */
export function createSsoAuthorizeHandler(cfg: SsoConfig, states: SsoStateStore): WebRoute['handler'] {
  return (req: IncomingMessage, res: ServerResponse) => {
    const state = states.issue()
    const redirectUri = resolveRedirectUri(cfg, req)
    ssoTrace(`authorize -> ${redirectUri}`)
    res.writeHead(302, { Location: buildAuthorizeUrl(cfg, state, redirectUri) })
    res.end()
  }
}

/**
 * Auto-provision the UserStore record for an SSO identity, with the 工号
 * allowlist as the admin authority: a uid on `cfg.ssoAdminUids` is provisioned
 * as admin — and an already-provisioned ordinary record is promoted on its
 * next SSO login — while a uid off the list is ordinary. An empty list keeps
 * the legacy first-ever-SSO-login-becomes-admin rule. The scrypt password is
 * random and unknowable — the SSO channel is the only way in for provisioned
 * accounts (password login remains for locally created users).
 *
 * 审批门（activated）：非空 allowlist 时，清单内工号建号即激活（预信任，直接登录）；
 * 清单外工号建号为待激活（`activated: false`），登录被挡到管理员放行。空清单不设门。
 */
export async function upsertSsoUser(
  users: UserStore,
  uid: string,
  adminUids: readonly string[] = [],
): Promise<UserRecord> {
  const records = await users.list()
  const existing = records.find(u => u.username === uid)
  const isAdmin = adminUids.length > 0
    ? adminUids.includes(uid)
    : existing?.isAdmin === true || records.length === 0
  if (existing !== undefined) {
    if (existing.isAdmin !== isAdmin) await users.setAdmin(uid, isAdmin)
    return existing.isAdmin === isAdmin ? existing : { ...existing, isAdmin }
  }
  const random = randomBytes(24).toString('hex')
  try {
    const record = await users.create(uid, random, isAdmin)
    if (record.isAdmin !== isAdmin) {
      // users.create force-admins the very first record (setup-flow rule);
      // the allowlist overrides that for SSO provisioning.
      await users.setAdmin(uid, isAdmin)
    }
    const activated = adminUids.length > 0 ? adminUids.includes(uid) : true
    if (!activated) await users.setActivated(uid, false)
    return { ...record, isAdmin, ...(activated ? {} : { activated: false }) }
  } catch {
    // Race with a concurrent first login, or a uid outside the username
    // pattern — re-lookup, then fail loudly (error redirect, no silent account).
    const again = (await users.list()).find(u => u.username === uid)
    if (again !== undefined) return again
    throw new Error(`cannot provision sso user "${uid}"`)
  }
}

/** GET /api/auth/sso/callback — consume state, exchange the code, log in. */
export function createSsoCallbackHandler(deps: SsoCallbackDeps): WebRoute['handler'] {
  return async (req: IncomingMessage, res: ServerResponse) => {
    const fail = (code: SsoErrorCode): void => {
      res.writeHead(302, { Location: `/login?error=${code}` })
      res.end()
    }
    const url = new URL(req.url ?? '/', 'http://x')
    const code = url.searchParams.get('code')
    const state = url.searchParams.get('state')
    const stateOk = state !== null && deps.states.consume(state)
    ssoTrace(`callback: state_ok=${stateOk ? 'y' : 'n'} code_len=${code?.length ?? 0}`)
    if (code === null || code.length === 0 || state === null || !stateOk) {
      return fail('sso_bad_state')
    }
    let secret: string | undefined
    try {
      secret = await deps.resolveSecret()
    } catch {
      secret = undefined
    }
    if (secret === undefined || secret.length === 0) return fail('sso_not_configured')
    const redirectUri = resolveRedirectUri(deps.cfg, req)
    let accessToken: string
    try {
      accessToken = await exchangeCode(deps.cfg, secret, code, redirectUri)
    } catch {
      ssoTrace('exchange: FAILED')
      return fail('sso_exchange_failed')
    }
    ssoTrace(`exchange: ok token_len=${accessToken.length}`)
    let info: Record<string, unknown>
    try {
      info = await fetchUserInfo(deps.cfg, accessToken)
    } catch {
      ssoTrace('userinfo: FAILED')
      return fail('sso_userinfo_failed')
    }
    ssoTrace(`userinfo: keys=${Object.keys(info).sort().join(',')}`)
    const uid = resolveUid(info, deps.cfg.ssoUidField)
    if (uid === undefined) {
      // 排障辅助：只记字段名，不记字段值（secret/token/code 同级红线）。
      console.warn('sso_no_uid: userinfo field names: %j', Object.keys(info).sort())
      return fail('sso_no_uid')
    }
    let record: UserRecord
    try {
      record = await upsertSsoUser(deps.users, uid, deps.cfg.ssoAdminUids)
    } catch {
      return fail('sso_provision_failed')
    }
    // 审批门：待激活账号不放会话——工号已入库，等管理员在用户管理里放行。
    if (record.activated === false) return fail('sso_pending_activation')
    const session = deps.store.create(record.username, record.isAdmin)
    res.setHeader('Set-Cookie', buildCookieHeader(session.token, deps.sessionTtl))
    res.writeHead(302, { Location: '/' })
    res.end()
  }
}

